const PR17=[{label:"Ví dụ: Chọn nhiều cuộc họp nhất",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    vector<pair<int, int>> a = {{1, 4}, {3, 5}, {0, 6}, {5, 7}, {3, 9}, {5, 9}, {6, 10}, {8, 11}};\n    // sắp theo giờ kết thúc: đổi thành (kết thúc, bắt đầu) để sort đúng ý\n    vector<pair<int, int>> b;\n    for (auto [s, e] : a) b.push_back({e, s});\n    sort(b.begin(), b.end());\n    int dem = 0, ketThuc = -1;\n    for (auto [e, s] : b)\n        if (s >= ketThuc) {            // không chồng với cuộc họp vừa chọn\n            dem++;\n            ketThuc = e;\n        }\n    cout << dem << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["s","e","dem","ketThuc"]}]},{label:"Ví dụ: Ghép thuyền bằng hai con trỏ",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    vector<int> w = {70, 50, 80, 50, 30, 60};\n    int x = 100;                       // mỗi thuyền chở tối đa 2 người, tổng cân ≤ x\n    sort(w.begin(), w.end());\n    int l = 0, r = w.size() - 1, thuyen = 0;\n    while (l <= r) {\n        if (l < r && w[l] + w[r] <= x) l++;   // người nhẹ nhất đi cùng người nặng nhất\n        r--;                           // người nặng nhất luôn xuống thuyền\n        thuyen++;\n    }\n    cout << thuyen << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"w",ptr:["l","r"]},{type:"vars",names:["thuyen"]}]},{label:"Lỗi: sắp theo giờ bắt đầu",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    vector<pair<int, int>> a = {{1, 10}, {2, 3}, {4, 5}};   // (bắt đầu, kết thúc)\n    sort(a.begin(), a.end());          // SAI: sắp theo giờ bắt đầu\n    int dem = 0, ketThuc = -1;\n    for (auto [s, e] : a)\n        if (s >= ketThuc) { dem++; ketThuc = e; }\n    cout << dem << \"\\n\";               // đúng phải là 2\n    return 0;\n}",viz:[{type:"vars",names:["s","e","dem","ketThuc"]}]}];
const sim17=makeSim2(document.getElementById("sim-l17"),{id:"s17",presets:PR17,tools:true});
makeEx2(document.getElementById("ex-l17"),sim17,[{t:"Lịch phòng họp",d:"File PHONGHOP.INP: dòng 1 là n (1 ≤ n ≤ 10⁵); n dòng sau mỗi dòng hai số s, e (0 ≤ s &lt; e ≤ 10⁹): giờ bắt đầu, kết thúc của một cuộc họp. Một phòng họp chỉ tổ chức được các cuộc họp không chồng nhau (cuộc sau được bắt đầu đúng lúc cuộc trước kết thúc). Ghi vào PHONGHOP.OUT số cuộc họp nhiều nhất có thể tổ chức.",tests:[{in:"8\n1 4\n3 5\n0 6\n5 7\n3 9\n5 9\n6 10\n8 11",out:"3"},{in:"3\n1 10\n2 3\n4 5",out:"2"},{in:"1\n1 2",out:"1"},{in:"3\n1 2\n2 3\n3 4",out:"3"},{in:"40\n66 80\n38 50\n37 43\n98 121\n90 108\n84 93\n14 15\n31 44\n95 109\n32 49\n40 61\n87 111\n51 56\n70 72\n17 43\n25 30\n90 108\n71 97\n87 94\n42 60\n15 38\n81 84\n39 53\n10 27\n60 81\n76 81\n87 113\n52 69\n43 44\n55 67\n73 75\n96 120\n45 47\n61 73\n74 99\n0 13\n30 34\n71 78\n31 48\n46 48",out:"14"},{in:"60\n8 10\n25 30\n6 9\n8 13\n29 35\n10 13\n10 12\n29 34\n10 11\n1 7\n0 8\n23 28\n15 16\n23 27\n9 14\n2 10\n0 3\n12 20\n23 30\n5 9\n8 11\n21 23\n29 33\n1 6\n25 31\n25 31\n1 4\n29 36\n2 7\n26 31\n21 28\n15 17\n17 19\n17 21\n7 12\n18 21\n25 30\n1 9\n18 25\n26 34\n7 14\n16 24\n2 10\n24 28\n7 15\n10 14\n11 12\n30 37\n1 7\n30 33\n29 33\n19 25\n11 14\n24 28\n9 16\n11 19\n18 20\n16 18\n16 17\n6 9",out:"10"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"PHONGHOP.INP\", \"r\")) {\n        freopen(\"PHONGHOP.INP\", \"r\", stdin);\n        freopen(\"PHONGHOP.OUT\", \"w\", stdout);\n    }\n    int n;\n    cin >> n;\n    vector<pair<long long, long long>> a(n);\n    for (auto& [s, e] : a) cin >> s >> e;\n    sort(a.begin(), a.end());          // sắp theo giờ bắt đầu\n    int dem = 0;\n    long long ketThuc = -1;\n    for (auto [s, e] : a)\n        if (s >= ketThuc) { dem++; ketThuc = e; }\n    cout << dem << \"\\n\";\n    return 0;\n}",file:"PHONGHOP",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>{const s=(i*7919)%(3*n);return s+" "+(s+1+(i*31)%50)}).join("\n"),ns:[200,800,3200],need:"nlogn",limit:n=>60*n*Math.log2(n)+2000,why:"Sắp xếp O(n log n) rồi duyệt một lần."}},{t:"Thuyền đôi",d:"File THUYEN.INP: dòng 1 là n, x (1 ≤ n ≤ 10⁵, 1 ≤ x ≤ 10⁹); dòng 2 là n số wᵢ (1 ≤ wᵢ ≤ x): cân nặng mỗi người. Mỗi thuyền chở tối đa hai người, tổng cân nặng không quá x. Ghi vào THUYEN.OUT số thuyền ít nhất.",tests:[{in:"6 100\n70 50 80 50 30 60",out:"4"},{in:"1 5\n5",out:"1"},{in:"4 2\n1 1 1 1",out:"2"},{in:"3 5\n3 3 3",out:"3"},{in:"40 100\n58 60 58 65 18 69 71 61 58 2 38 34 24 2 60 44 97 43 28 7 35 13 67 86 90 2 4 15 61 91 39 79 27 100 13 100 4 59 69 98",out:"22"},{in:"50 60\n15 42 2 26 8 28 4 48 35 4 13 35 17 18 23 23 35 38 27 26 1 34 49 22 6 49 48 3 41 47 19 21 21 8 22 9 35 16 32 19 29 8 17 16 5 44 27 20 44 13",out:"25"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"THUYEN.INP\", \"r\")) {\n        freopen(\"THUYEN.INP\", \"r\", stdin);\n        freopen(\"THUYEN.OUT\", \"w\", stdout);\n    }\n    int n;\n    long long x;\n    cin >> n >> x;\n    vector<long long> w(n);\n    for (auto& v : w) cin >> v;\n    sort(w.begin(), w.end());\n    vector<bool> daDi(n, false);\n    int thuyen = 0;\n    for (int i = n - 1; i >= 0; i--) {         // người nặng nhất tìm bạn nặng nhất còn vừa\n        if (daDi[i]) continue;\n        daDi[i] = true;\n        thuyen++;\n        for (int j = i - 1; j >= 0; j--)\n            if (!daDi[j] && w[i] + w[j] <= x) { daDi[j] = true; break; }\n    }\n    cout << thuyen << \"\\n\";\n    return 0;\n}",file:"THUYEN",perf:{gen:n=>n+" "+1000+"\n"+Array.from({length:n},(_,i)=>1+(i*7919)%1000).join(" "),ns:[200,800,3200],need:"nlogn",limit:n=>60*n*Math.log2(n)+2000,why:"Quét tìm bạn cho từng người là O(n²); hai con trỏ sau khi sắp xếp là O(n log n)."}},{t:"Công việc và hạn chót",d:"File HANCHOT.INP: dòng 1 là n (1 ≤ n ≤ 10⁵); n dòng sau mỗi dòng hai số a, d (1 ≤ a, d ≤ 10⁶): thời lượng và hạn chót của một việc. Làm lần lượt mọi việc, bắt đầu từ thời điểm 0, không nghỉ. Việc xong ở thời điểm f được d − f điểm (có thể âm). Ghi vào HANCHOT.OUT tổng điểm lớn nhất.",tests:[{in:"3\n6 10\n8 15\n5 12",out:"2"},{in:"1\n1 1",out:"0"},{in:"2\n5 1\n1 5",out:"-1"},{in:"5\n1000000 1\n1000000 1\n1000000 1\n1000000 1\n1000000 1",out:"-14999995"},{in:"40\n16 47\n5 28\n17 74\n5 38\n3 56\n15 68\n13 100\n17 78\n5 85\n18 19\n6 76\n18 41\n16 37\n14 9\n20 31\n6 92\n5 100\n8 55\n18 42\n18 98\n15 97\n17 17\n10 32\n16 33\n17 25\n12 1\n4 43\n16 10\n14 12\n17 49\n8 22\n3 38\n3 37\n11 98\n15 42\n5 20\n9 40\n13 42\n19 66\n5 56",out:"-5249"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"HANCHOT.INP\", \"r\")) {\n        freopen(\"HANCHOT.INP\", \"r\", stdin);\n        freopen(\"HANCHOT.OUT\", \"w\", stdout);\n    }\n    int n;\n    cin >> n;\n    vector<pair<long long, long long>> v(n);   // (hạn chót, thời lượng)\n    for (auto& [d, a] : v) cin >> a >> d;\n    sort(v.begin(), v.end());          // làm việc có hạn chót sớm trước\n    long long t = 0, diem = 0;\n    for (auto [d, a] : v) { t += a; diem += d - t; }\n    cout << diem << \"\\n\";\n    return 0;\n}",file:"HANCHOT",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>(1+(i*7919)%1000)+" "+((i*31)%100000)).join("\n"),ns:[200,800,3200],need:"nlogn",limit:n=>60*n*Math.log2(n)+2000,why:"Sắp xếp O(n log n) rồi duyệt một lần."}}]);

